import{_ as t,o as e,c as n,a2 as o}from"./chunks/framework.DIWxYxwh.js";const k=JSON.parse('{"title":"系统提示词大部分相同时的 Prefix Caching 调度流程","description":"","frontmatter":{},"headers":[],"relativePath":"LLM推理/Prefix Caching.md","filePath":"LLM推理/Prefix Caching.md","lastUpdated":1791972048000}'),i={name:"LLM推理/Prefix Caching.md"};function l(s,a,r,h,c,d){return e(),n("div",null,[...a[0]||(a[0]=[o(`<h1 id="系统提示词大部分相同时的-prefix-caching-调度流程" tabindex="-1">系统提示词大部分相同时的 Prefix Caching 调度流程 <a class="header-anchor" href="#系统提示词大部分相同时的-prefix-caching-调度流程" aria-label="Permalink to &quot;系统提示词大部分相同时的 Prefix Caching 调度流程&quot;">​</a></h1><h2 id="一、场景设定" tabindex="-1">一、场景设定 <a class="header-anchor" href="#一、场景设定" aria-label="Permalink to &quot;一、场景设定&quot;">​</a></h2><p>实际服务中，很多请求共享同一段系统提示词。典型结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[系统提示词 L_sys token] + [用户输入 L_user token] = 总 prompt L_total token</span></span></code></pre></div><p>示例参数如下，<strong>不是任何一次真实测试的结果，只是用来演示计算方式</strong>。</p><table tabindex="0"><thead><tr><th>项目</th><th>值</th></tr></thead><tbody><tr><td><code>block_size</code></td><td>16</td></tr><tr><td>系统提示词 <code>L_sys</code></td><td>2000 token</td></tr><tr><td>用户输入 <code>L_user</code></td><td>536 token</td></tr><tr><td>总 prompt <code>L_total</code></td><td>2536 token</td></tr><tr><td><code>max_num_batched_tokens</code></td><td>2048</td></tr><tr><td>请求数</td><td>4 条</td></tr><tr><td>系统提示词</td><td>4 条完全相同</td></tr><tr><td>用户输入</td><td>4 条各不相同</td></tr></tbody></table><p>4 条请求的结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求 A：[系统提示词 2000] + [用户输入 A 536]</span></span>
<span class="line"><span>请求 B：[系统提示词 2000] + [用户输入 B 536]</span></span>
<span class="line"><span>请求 C：[系统提示词 2000] + [用户输入 C 536]</span></span>
<span class="line"><span>请求 D：[系统提示词 2000] + [用户输入 D 536]</span></span></code></pre></div><hr><h2 id="二、第一个请求-完整-prefill-写入-hash-表" tabindex="-1">二、第一个请求：完整 Prefill，写入 Hash 表 <a class="header-anchor" href="#二、第一个请求-完整-prefill-写入-hash-表" aria-label="Permalink to &quot;二、第一个请求：完整 Prefill，写入 Hash 表&quot;">​</a></h2><p><strong>请求 A 到达，总 prompt 2536 token。</strong></p><h3 id="_2-1-查找-prefix-caching" tabindex="-1">2.1 查找 Prefix Caching <a class="header-anchor" href="#_2-1-查找-prefix-caching" aria-label="Permalink to &quot;2.1 查找 Prefix Caching&quot;">​</a></h3><p>调度器计算请求 A 第一个 block 的 hash，去全局 hash 表查找。<strong>此时缓存是空的，全部未命中。</strong></p><h3 id="_2-2-分配新-block-执行-prefill" tabindex="-1">2.2 分配新 Block，执行 Prefill <a class="header-anchor" href="#_2-2-分配新-block-执行-prefill" aria-label="Permalink to &quot;2.2 分配新 Block，执行 Prefill&quot;">​</a></h3><p>从空闲队列分配 block。2536 token 需要：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ceil(2536 / 16) = 159 个 block</span></span></code></pre></div><p><code>max_num_batched_tokens = 2048</code>，prefill 分步：</p><ul><li><strong>第 1 步</strong>：算前 2048 token。前 2000 token 是系统提示词，后 48 token 是用户输入开头。填满前 128 个 block（2048 / 16 = 128）。</li><li><strong>第 2 步</strong>：算剩余 488 token。填满后续 31 个 block（488 / 16 ≈ 30.5，最后一个 block 未满）。</li></ul><h3 id="_2-3-写入-hash-表" tabindex="-1">2.3 写入 Hash 表 <a class="header-anchor" href="#_2-3-写入-hash-表" aria-label="Permalink to &quot;2.3 写入 Hash 表&quot;">​</a></h3><p>每当一个 block 被填满，vLLM 计算它的 hash 并写入全局 hash 表。</p><table tabindex="0"><thead><tr><th>Block</th><th>Hash 输入</th><th>是否与用户输入有关</th></tr></thead><tbody><tr><td>1</td><td>系统提示词第 1–16 token</td><td>无关</td></tr><tr><td>2</td><td>系统提示词第 1–32 token</td><td>无关</td></tr><tr><td>…</td><td>…</td><td>无关</td></tr><tr><td>125</td><td>系统提示词第 1–2000 token</td><td>无关</td></tr><tr><td>126</td><td>系统提示词 2000 + 用户输入第 1–16 token</td><td>有关</td></tr><tr><td>…</td><td>…</td><td>有关</td></tr><tr><td>128</td><td>系统提示词 + 用户输入前 2048 token</td><td>有关</td></tr><tr><td>159</td><td>全部 2536 token</td><td>有关</td></tr></tbody></table><p><strong>关键点</strong>：前 125 个 block（覆盖整个系统提示词 2000 token）的 hash <strong>只依赖系统提示词本身</strong>，和用户输入无关。这 125 个 block 的 hash 对所有请求都是一样的。</p><h3 id="_2-4-解码阶段" tabindex="-1">2.4 解码阶段 <a class="header-anchor" href="#_2-4-解码阶段" aria-label="Permalink to &quot;2.4 解码阶段&quot;">​</a></h3><p>请求 A 进入 decode，每生成一个 token 就写 KV，block 满则分配新 block。这些新 block 的 hash 也写入表，但因为它们位于用户输入和输出之后，不会被后续请求复用。</p><hr><h2 id="三、第二个请求-命中前-125-个-block" tabindex="-1">三、第二个请求：命中前 125 个 Block <a class="header-anchor" href="#三、第二个请求-命中前-125-个-block" aria-label="Permalink to &quot;三、第二个请求：命中前 125 个 Block&quot;">​</a></h2><p><strong>请求 B 到达，系统提示词与 A 完全相同，用户输入不同。</strong></p><h3 id="_3-1-查找-prefix-caching" tabindex="-1">3.1 查找 Prefix Caching <a class="header-anchor" href="#_3-1-查找-prefix-caching" aria-label="Permalink to &quot;3.1 查找 Prefix Caching&quot;">​</a></h3><p>调度器计算请求 B 第一个 block 的 hash：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hash(系统提示词第 1–16 token)</span></span></code></pre></div><p>这个 hash <strong>和请求 A 的第一个 block hash 完全相同</strong>。命中。</p><p>继续查第二个 block：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hash(系统提示词第 1–32 token)</span></span></code></pre></div><p>和请求 A 的第二个 block hash 相同。命中。</p><p><strong>这个过程一直持续到第 125 个 block。</strong> 因为前 125 个 block 的 hash 只依赖系统提示词，而 B 的系统提示词和 A 完全一样，所以这 125 个 block 全部命中。</p><p>到了第 126 个 block：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hash(系统提示词 2000 + 用户输入第 1–16 token)</span></span></code></pre></div><p>请求 B 的用户输入和 A 不同，这个 hash 和 A 的第 126 个 block hash <strong>不同</strong>。未命中。</p><p><strong>匹配到此为止。</strong> 请求 B 复用了前 125 个 block 的 KV，即整个系统提示词的 2000 token。</p><h3 id="_3-2-为未命中部分分配新-block" tabindex="-1">3.2 为未命中部分分配新 Block <a class="header-anchor" href="#_3-2-为未命中部分分配新-block" aria-label="Permalink to &quot;3.2 为未命中部分分配新 Block&quot;">​</a></h3><p>请求 B 只需要为“用户输入 536 token”分配新 block：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ceil(536 / 16) = 34 个 block</span></span></code></pre></div><p>这 34 个 block 从空闲队列分配，执行 prefill。</p><h3 id="_3-3-prefill-计算量对比" tabindex="-1">3.3 Prefill 计算量对比 <a class="header-anchor" href="#_3-3-prefill-计算量对比" aria-label="Permalink to &quot;3.3 Prefill 计算量对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>请求</th><th>系统提示词 prefill</th><th>用户输入 prefill</th><th>总 prefill</th></tr></thead><tbody><tr><td>A（第一个）</td><td>2000 token</td><td>536 token</td><td>2536 token</td></tr><tr><td>B（后续）</td><td>0（命中复用）</td><td>536 token</td><td>536 token</td></tr></tbody></table><p><strong>请求 B 省掉了 2000 token 的 prefill 计算，节省约 79%。</strong></p><h3 id="_3-4-引用计数" tabindex="-1">3.4 引用计数 <a class="header-anchor" href="#_3-4-引用计数" aria-label="Permalink to &quot;3.4 引用计数&quot;">​</a></h3><p>请求 A 的前 125 个 block，<code>ref_cnt</code> 从 1 变成 2。请求 B 和请求 A 共享这 125 个物理 block。</p><hr><h2 id="四、后续请求与引用计数变化" tabindex="-1">四、后续请求与引用计数变化 <a class="header-anchor" href="#四、后续请求与引用计数变化" aria-label="Permalink to &quot;四、后续请求与引用计数变化&quot;">​</a></h2><p><strong>请求 C、D 陆续到达</strong>，系统提示词相同。</p><p>每个请求都会命中前 125 个 block，<code>ref_cnt</code> 依次变成 3、4。</p><h3 id="_4-1-请求结束时发生什么" tabindex="-1">4.1 请求结束时发生什么 <a class="header-anchor" href="#_4-1-请求结束时发生什么" aria-label="Permalink to &quot;4.1 请求结束时发生什么&quot;">​</a></h3><p><strong>请求 A 结束</strong>：</p><ul><li>A 释放自己引用的所有 block。</li><li>前 125 个 block 的 <code>ref_cnt</code> 减一（从 4 变成 3），<strong>因为还有 B、C、D 在用，不会被回收</strong>。</li><li>A 独有的用户输入和输出部分的 block，<code>ref_cnt</code> 归 0，回到空闲队列。</li></ul><p><strong>所有请求都结束</strong>：</p><ul><li>前 125 个 block 的 <code>ref_cnt</code> 归 0。</li><li>但它们<strong>不会立即被清空</strong>，而是留在池子里。</li><li>下一个新请求到来时，如果系统提示词相同，仍然能命中这 125 个 block，<strong>不需要重新 prefill 系统提示词</strong>。</li></ul><h3 id="_4-2-什么时候会被淘汰" tabindex="-1">4.2 什么时候会被淘汰 <a class="header-anchor" href="#_4-2-什么时候会被淘汰" aria-label="Permalink to &quot;4.2 什么时候会被淘汰&quot;">​</a></h3><p>如果长时间没有新请求命中这 125 个 block，且空闲 block 不足，它们会按 LRU 被淘汰。但只要系统提示词还在被使用，这些 block 的访问时间总是很新，<strong>最不容易被淘汰</strong>。</p><hr><h2 id="五、ttft-的变化" tabindex="-1">五、TTFT 的变化 <a class="header-anchor" href="#五、ttft-的变化" aria-label="Permalink to &quot;五、TTFT 的变化&quot;">​</a></h2><p>回到调度流程的核心问题：Prefix Caching 怎么影响 TTFT。</p><h3 id="_5-1-无-prefix-caching" tabindex="-1">5.1 无 Prefix Caching <a class="header-anchor" href="#_5-1-无-prefix-caching" aria-label="Permalink to &quot;5.1 无 Prefix Caching&quot;">​</a></h3><p><strong>并发 2，两条请求都带 2000 token 系统提示词</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>两条合计 = 2 × 2536 = 5072 token</span></span></code></pre></div><p><code>max_num_batched_tokens = 2048</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>prefill 步数 = ceil(5072 / 2048) = 3 步</span></span>
<span class="line"><span>TTFT ≈ T_固定 + 3 × f(2048) + 排队</span></span></code></pre></div><h3 id="_5-2-有-prefix-caching-但第一批请求" tabindex="-1">5.2 有 Prefix Caching，但第一批请求 <a class="header-anchor" href="#_5-2-有-prefix-caching-但第一批请求" aria-label="Permalink to &quot;5.2 有 Prefix Caching，但第一批请求&quot;">​</a></h3><p>缓存还是空的，两条都要算完整 2536 token：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>和无 Prefix Caching 一样，3 步</span></span></code></pre></div><h3 id="_5-3-有-prefix-caching-且系统提示词已在缓存中" tabindex="-1">5.3 有 Prefix Caching，且系统提示词已在缓存中 <a class="header-anchor" href="#_5-3-有-prefix-caching-且系统提示词已在缓存中" aria-label="Permalink to &quot;5.3 有 Prefix Caching，且系统提示词已在缓存中&quot;">​</a></h3><p>两条各只需算 536 token 用户输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>两条合计 = 2 × 536 = 1072 token</span></span></code></pre></div><p><code>1072 &lt; 2048</code>，<strong>一步 prefill 完</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TTFT ≈ T_固定 + f(1072)</span></span></code></pre></div><p><strong>和无缓存时的 3 步相比，TTFT 大幅下降。</strong></p><h3 id="_5-4-对比表" tabindex="-1">5.4 对比表 <a class="header-anchor" href="#_5-4-对比表" aria-label="Permalink to &quot;5.4 对比表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>prefill token 数</th><th>prefill 步数</th><th>TTFT</th></tr></thead><tbody><tr><td>无 Prefix Caching，并发 2</td><td>5072</td><td>3</td><td>高</td></tr><tr><td>有缓存，第一批，并发 2</td><td>5072</td><td>3</td><td>高</td></tr><tr><td>有缓存，命中后，并发 2</td><td>1072</td><td>1</td><td>低</td></tr></tbody></table><p><strong>Prefix Caching 对 TTFT 最直接的影响</strong>：把“每条请求都要算系统提示词”变成“只有第一个请求算，后续请求直接复用”，让同一步里的 prefill token 数大幅减少。</p><hr><h2 id="六、chunked-prefill-与-prefix-caching-的交互" tabindex="-1">六、Chunked Prefill 与 Prefix Caching 的交互 <a class="header-anchor" href="#六、chunked-prefill-与-prefix-caching-的交互" aria-label="Permalink to &quot;六、Chunked Prefill 与 Prefix Caching 的交互&quot;">​</a></h2><p>如果开启了 chunked prefill（默认开启），有一个关键细节：</p><p><strong>Prefix Caching 的查找只在第一个 chunk 执行。</strong></p><p>假设请求 prompt 2536 token，<code>max_num_batched_tokens = 2048</code>，需要切 2 个 chunk：</p><p><strong>第 1 个 chunk</strong>：2048 token。</p><ul><li>调度器先查 Prefix Caching，命中前 125 个 block（2000 token）。</li><li>这 125 个 block 直接复用，不需要计算。</li><li>剩余 48 token（用户输入开头）需要计算。</li><li>这一步实际只算 48 token。</li></ul><p><strong>第 2 个 chunk</strong>：488 token。</p><ul><li><strong>不再查 Prefix Caching</strong>，直接计算。</li></ul><p>所以有 Prefix Caching 时，请求 B 的 prefill 实际计算量：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1 chunk：48 token（系统提示词命中，用户输入开头 48 token）</span></span>
<span class="line"><span>第 2 chunk：488 token（用户输入剩余）</span></span>
<span class="line"><span>合计：536 token</span></span></code></pre></div><p>和无 Prefix Caching 时的 2536 token 相比，节省了 2000 token。</p><hr><h2 id="七、block-的回收与淘汰" tabindex="-1">七、Block 的回收与淘汰 <a class="header-anchor" href="#七、block-的回收与淘汰" aria-label="Permalink to &quot;七、Block 的回收与淘汰&quot;">​</a></h2><p>在有共享系统提示词的场景下，前 125 个 block 的 <code>ref_cnt</code> 通常很高（等于活跃请求数）。<strong>只要还有请求在用，它们就不会被淘汰。</strong></p><p>当活跃请求数降为 0，这 125 个 block 的 <code>ref_cnt</code> 归 0，但仍在池子里。如果此时空闲 block 不足，vLLM 按 LRU 淘汰。<strong>共享系统提示词的 block 因为访问频繁，最后访问时间总是很新，所以最不容易被淘汰。</strong> 只有长期没有新请求命中它们，才会被回收。</p><hr><h2 id="八、使用-prefix-caching-的注意事项" tabindex="-1">八、使用 Prefix Caching 的注意事项 <a class="header-anchor" href="#八、使用-prefix-caching-的注意事项" aria-label="Permalink to &quot;八、使用 Prefix Caching 的注意事项&quot;">​</a></h2><h3 id="_8-1-让系统提示词尽量长" tabindex="-1">8.1 让系统提示词尽量长 <a class="header-anchor" href="#_8-1-让系统提示词尽量长" aria-label="Permalink to &quot;8.1 让系统提示词尽量长&quot;">​</a></h3><p>至少填满多个 block（16 token 一个），命中的粒度更粗，收益更大。2000 token 的系统提示词能命中 125 个 block，收益显著。</p><h3 id="_8-2-确保系统提示词的-token-序列完全一致" tabindex="-1">8.2 确保系统提示词的 token 序列完全一致 <a class="header-anchor" href="#_8-2-确保系统提示词的-token-序列完全一致" aria-label="Permalink to &quot;8.2 确保系统提示词的 token 序列完全一致&quot;">​</a></h3><p>任何 token 不同（包括空格、换行、标点），都会导致后续所有 block 的 hash 改变，命中失败。</p><h3 id="_8-3-注意系统提示词和用户输入的边界" tabindex="-1">8.3 注意系统提示词和用户输入的边界 <a class="header-anchor" href="#_8-3-注意系统提示词和用户输入的边界" aria-label="Permalink to &quot;8.3 注意系统提示词和用户输入的边界&quot;">​</a></h3><p>用户输入的第一个 block 因为和系统提示词拼在一起，hash 会变，不会被复用。这没关系，因为用户输入本来每条都不同。</p><h3 id="_8-4-冷启动要预热" tabindex="-1">8.4 冷启动要预热 <a class="header-anchor" href="#_8-4-冷启动要预热" aria-label="Permalink to &quot;8.4 冷启动要预热&quot;">​</a></h3><p>Prefix Caching 只对“已经缓存过的前缀”有效，冷启动时第一批请求没有收益。可以在服务启动后先打几条预热请求，把系统提示词的 block 写进缓存。</p><h3 id="_8-5-prefix-caching-不改变单路解码速度" tabindex="-1">8.5 Prefix Caching 不改变单路解码速度 <a class="header-anchor" href="#_8-5-prefix-caching-不改变单路解码速度" aria-label="Permalink to &quot;8.5 Prefix Caching 不改变单路解码速度&quot;">​</a></h3><p>它只减少 prefill 计算量，降低 TTFT，不改变 TPOT。单路解码速度由带宽和算力决定，Prefix Caching 帮不上忙。</p><h3 id="_8-6-系统提示词长度和-block-边界" tabindex="-1">8.6 系统提示词长度和 Block 边界 <a class="header-anchor" href="#_8-6-系统提示词长度和-block-边界" aria-label="Permalink to &quot;8.6 系统提示词长度和 Block 边界&quot;">​</a></h3><p>如果系统提示词的 token 数不是 16 的整数倍，最后一个 block 会包含系统提示词结尾和用户输入开头。这个 block 的 hash 依赖用户输入，<strong>不会被后续请求命中</strong>。所以系统提示词长度最好对齐到 block 边界，让最后一个系统提示词 block 完全由系统提示词组成。</p><hr><h2 id="九、一句话总结" tabindex="-1">九、一句话总结 <a class="header-anchor" href="#九、一句话总结" aria-label="Permalink to &quot;九、一句话总结&quot;">​</a></h2><p><strong>系统提示词大部分相同时，Prefix Caching 的调度流程是：第一个请求完整 prefill 系统提示词并写入 block hash 表；后续请求按 block 逐级匹配 hash，命中则直接复用 KV、跳过 prefill，未命中部分（用户输入）才分配新 block 计算。命中粒度是 block（16 token），匹配要求 token 级完全一致。引用计数保证共享 block 在有请求使用时不被回收，LRU 保证长期不用的 block 最终被淘汰。系统提示词越长、越一致、越对齐 block 边界，命中收益越大。冷启动时第一批请求没有收益，需要预热。Prefix Caching 只降低 TTFT，不改变 TPOT。</strong></p>`,112)])])}const b=t(i,[["render",l]]);export{k as __pageData,b as default};
